<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { cancelProductBatch, exportProductBatchFailures, getProductBatch, getProductBatches, newRequestId, retryProductBatch } from '@/api/matrix'
import { getAccountList } from '@/api/account'
import { showError, showSuccess } from '@/utils'
import { useModalFocusTrap } from '@/composables/useModalFocusTrap'
import type { Account } from '@/types'

const jobs=ref<Record<string,any>[]>([]),selected=ref<Record<string,any>|null>(null),loading=ref(false),detailLoading=ref(false),error=ref(''),retryIds=ref<number[]>([]),accounts=ref<Account[]>([])
const filter=reactive({search:'',status:'',operationType:'',accountId:undefined as number|undefined,operatorUserId:undefined as number|undefined,createdFrom:'',createdTo:''})
const cancelDialog=ref(false),cancelReason=ref('用户停止未执行商品'),cancelling=ref(false)
useModalFocusTrap(cancelDialog,()=>document.querySelector<HTMLElement>('.cancel-dialog'))
let timer:number|undefined
const active=computed(()=>jobs.value.some(j=>['QUEUED','RUNNING','CANCEL_REQUESTED'].includes(j.status)))
const label=(v?:string)=>({QUEUED:'排队中',RUNNING:'运行中',SUCCEEDED:'成功',FAILED:'失败',PARTIAL_SUCCESS:'部分成功',CANCEL_REQUESTED:'取消中',CANCELLED:'已取消',UNKNOWN:'结果未知',SKIPPED:'已跳过',CONFLICT:'预检冲突',SYNC:'同步',POLISH:'擦亮',ON_SALE:'上架',OFF_SHELF:'下架',CHANGE_PRICE:'改价',CHANGE_STOCK:'改库存',DELETE:'删除'}[v||'']||v||'—')
const tone=(v?:string)=>v==='SUCCEEDED'?'good':['FAILED','UNKNOWN'].includes(v||'')?'bad':['RUNNING','PARTIAL_SUCCESS','CANCEL_REQUESTED'].includes(v||'')?'warn':'muted'
const time=(v?:string)=>v?new Date(v).toLocaleString('zh-CN'):'—'
const load=async(silent=false)=>{if(!silent)loading.value=true;error.value='';try{const r=await getProductBatches({...filter,accountId:filter.accountId||undefined,operatorUserId:filter.operatorUserId||undefined,createdFrom:filter.createdFrom||undefined,createdTo:filter.createdTo||undefined,limit:200});jobs.value=r.data||[];if(selected.value){const latest=jobs.value.find(j=>j.jobId===selected.value?.jobId);if(latest&&['QUEUED','RUNNING','CANCEL_REQUESTED'].includes(latest.status))await open(latest,true)}}catch(e:any){error.value=e.message||'任务列表读取失败'}finally{loading.value=false}}
const open=async(job:Record<string,any>,silent=false)=>{if(!silent)detailLoading.value=true;try{const r=await getProductBatch(job.jobId);selected.value=r.data||null;retryIds.value=[];await nextTick();document.querySelector<HTMLElement>('.task-detail')?.scrollTo({top:0})}catch(e:any){showError(e.message||'任务详情读取失败')}finally{detailLoading.value=false}}
const requestCancel=()=>{cancelReason.value='用户停止未执行商品';cancelDialog.value=true}
const cancel=async()=>{if(!selected.value||!cancelReason.value.trim())return showError('请填写取消原因');cancelling.value=true;try{await cancelProductBatch(selected.value.jobId,newRequestId('batch-cancel'),cancelReason.value.trim());cancelDialog.value=false;showSuccess('已请求安全取消，已执行项不会回滚');await load()}finally{cancelling.value=false}}
const retry=async()=>{if(!selected.value||!retryIds.value.length)return showError('请选择可安全重试的失败项');await retryProductBatch(selected.value.jobId,selected.value.operationType,retryIds.value,newRequestId('batch-retry'));showSuccess(`已重新排队 ${retryIds.value.length} 项`);await load();await open(selected.value,true)}
const exportFailures=async()=>{if(!selected.value)return;try{const blob=await exportProductBatchFailures(selected.value.jobId,newRequestId('batch-export'));const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=`${selected.value.batchId}-failures.csv`;a.click();window.setTimeout(()=>URL.revokeObjectURL(url),1000);showSuccess('失败明细 CSV 已生成并记录审计')}catch(e:any){showError(e.message||'失败明细导出失败')}}
const canRetry=(i:Record<string,any>)=>i.status==='FAILED'
onMounted(async()=>{const accountResult=await Promise.allSettled([getAccountList()]);if(accountResult[0].status==='fulfilled')accounts.value=accountResult[0].value.data?.accounts||[];await load();timer=window.setInterval(()=>{if(active.value)void load(true)},8000)})
onBeforeUnmount(()=>{if(timer)window.clearInterval(timer)})
</script>

<template>
  <main class="task-center">
    <header class="task-center__header"><div><span class="eyebrow">PRD-04 · 持久化任务</span><h1>商品任务中心</h1><p>平台结果、本地结果、未知状态与取消边界逐件留痕。</p></div><button class="primary" :disabled="loading" @click="load()">刷新任务</button></header>
    <section class="task-center__filters" aria-label="任务筛选"><input v-model="filter.search" placeholder="任务 ID / 请求 ID" @keyup.enter="load()"><select v-model="filter.status"><option value="">全部状态</option><option v-for="s in ['QUEUED','RUNNING','SUCCEEDED','PARTIAL_SUCCESS','FAILED','CANCEL_REQUESTED','CANCELLED']" :key="s" :value="s">{{ label(s) }}</option></select><select v-model="filter.operationType"><option value="">全部动作</option><option v-for="s in ['SYNC','ON_SALE','OFF_SHELF','POLISH','CHANGE_PRICE','CHANGE_STOCK','DELETE']" :key="s" :value="s">{{ label(s) }}</option></select><select v-model="filter.accountId"><option :value="undefined">全部店铺</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{ a.accountNote||a.unb }}</option></select><input v-model.number="filter.operatorUserId" type="number" min="1" placeholder="操作人 ID" aria-label="操作人 ID"><input v-model="filter.createdFrom" type="datetime-local" aria-label="开始时间"><input v-model="filter.createdTo" type="datetime-local" aria-label="结束时间"><button @click="load()">筛选</button></section>
    <div v-if="loading&&jobs.length" class="state-banner">正在更新，已保留当前任务列表…</div><div v-if="error" class="state-banner state-banner--error" role="alert"><span>{{ error }}</span><button @click="load()">重试</button></div>
    <div v-if="selected?.executionChannel==='QA_MOCK'" class="qa-evidence" role="status"><div><strong>隔离 QA Mock · 不触达闲鱼平台</strong><span>此任务通过真实持久化状态机运行，但平台响应来自隔离测试替身。</span></div><code>{{ selected.notificationEvidence?.route||'通知证据将在任务终态生成' }} · 外部发送 {{ selected.notificationEvidence?.externalDispatched===false?'否':'待确认' }}</code></div>
    <section class="task-layout"><div class="task-list"><div v-if="loading&&!jobs.length" class="empty">正在读取持久化任务…</div><div v-else-if="!jobs.length&&!error" class="empty">当前筛选范围没有任务。</div><button v-for="j in jobs" :key="j.jobId" class="task-card" :class="{active:selected?.jobId===j.jobId}" @click="open(j)"><div><strong>{{ label(j.operationType) }}</strong><span :class="['pill',tone(j.status)]">{{ label(j.status) }}</span></div><code>{{ j.batchId }}</code><div class="progress"><i :style="{width:`${j.progressPercent||0}%`}"></i></div><small>成功 {{ j.successCount }} · 失败 {{ j.failedCount }} · 未知 {{ j.unknownCount }} · 跳过 {{ j.skippedCount }}</small><small>每店 {{ j.maxOperationsPerMinute }} 次/分钟 · 等待上界约 {{ j.estimatedWaitSecondsUpperBound||0 }} 秒</small><small>{{ j.operatorUsername||'系统' }} · {{ time(j.createdTime) }}</small></button></div>
      <aside class="task-detail" :aria-busy="detailLoading"><div v-if="!selected" class="empty">选择一个任务查看逐件结果。</div><template v-else><header><div><span class="eyebrow">{{ label(selected.operationType) }} · {{ label(selected.status) }}</span><h2>{{ selected.batchId }}</h2><p>请求 {{ selected.requestId }} · 幂等键 {{ selected.idempotencyKey }}</p><p>每店 {{ selected.maxOperationsPerMinute }} 次/分钟 · 剩余等待上界约 {{ selected.estimatedWaitSeconds??selected.estimatedWaitSecondsUpperBound??0 }} 秒</p></div><button aria-label="关闭详情" @click="selected=null">×</button></header><section class="task-stats"><div><b>{{ selected.progressPercent||0 }}%</b><span>进度</span></div><div><b>{{ selected.successCount }}</b><span>成功</span></div><div><b>{{ selected.failedCount }}</b><span>失败</span></div><div><b>{{ selected.unknownCount }}</b><span>未知</span></div><div><b>{{ selected.cancelledCount }}</b><span>取消</span></div></section><div v-if="selected.unknownRequiresManualReview" class="unknown-note">存在“结果未知”子项：系统不会自动重试，请按平台请求 ID 人工核对。</div><div class="task-items"><article v-for="i in selected.items" :key="i.itemId"><input v-if="canRetry(i)" v-model="retryIds" type="checkbox" :value="i.itemId" :aria-label="`选择重试 ${i.title||i.goodsId}`"><span v-else class="checkbox-placeholder"></span><div><strong>{{ i.title||i.goodsId }}</strong><small>{{ i.accountNote||`店铺 ${i.accountId}` }} · {{ i.goodsId }}</small><details><summary>旧值 / 新值 / 请求证据</summary><pre>{{ JSON.stringify({old:i.oldValue,new:i.newValue,platformRequestId:i.platformRequestId,errorCode:i.errorCode},null,2) }}</pre></details></div><span :class="['pill',tone(i.status)]">{{ label(i.status) }}</span><small>尝试 {{ i.attemptCount }}/{{ i.maxAttempts }}<br>{{ i.nextRetryTime?`退避至 ${time(i.nextRetryTime)}`:(i.errorMessage||i.conflictMessage||time(i.completedTime)) }}</small></article></div><footer><button @click="exportFailures">导出失败明细</button><button :disabled="!retryIds.length" @click="retry">重试所选失败项</button><button class="danger" :disabled="!['QUEUED','RUNNING','CANCEL_REQUESTED'].includes(selected.status)" @click="requestCancel">安全取消</button></footer></template></aside></section>
    <div v-if="cancelDialog" class="dialog-backdrop" @click.self="cancelDialog=false"><section class="cancel-dialog" role="dialog" aria-modal="true" aria-labelledby="cancel-title"><header><div><span class="eyebrow">安全取消</span><h2 id="cancel-title">停止未开始的子任务</h2></div><button aria-label="关闭取消弹窗" @click="cancelDialog=false">×</button></header><p>已成功或正在执行的商品不会回滚；只取消尚未开始的子项。</p><label>取消原因<textarea v-model="cancelReason" maxlength="500" rows="3" data-autofocus></textarea></label><footer><button @click="cancelDialog=false">返回</button><button class="danger" :disabled="cancelling||!cancelReason.trim()" @click="cancel">确认安全取消</button></footer></section></div>
  </main>
</template>

<style scoped>
.task-center{max-width:1680px;margin:auto;color:#24231f}.task-center__header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:16px}.task-center h1{margin:5px 0;font-size:28px}.task-center p{margin:0;color:#747067}.eyebrow{color:#966800;font-size:11px;font-weight:750;letter-spacing:.08em}.primary,.task-center button{min-height:38px;border:1px solid #d9d5ca;border-radius:10px;background:#fff}.primary{padding:0 18px;border-color:#f0c52e;background:#ffd84a;font-weight:700}.task-center__filters{display:grid;grid-template-columns:1.5fr repeat(6,minmax(130px,.7fr)) auto;gap:8px;padding:12px;border:1px solid #e5e1d7;border-radius:14px;background:#fff}.task-center__filters input,.task-center__filters select{min-height:40px;padding:0 10px;border:1px solid #dcd8ce;border-radius:9px;background:#fff}.state-banner{display:flex;justify-content:space-between;margin-top:10px;padding:10px 13px;border-radius:10px;background:#fff8db;color:#765500}.state-banner--error{background:#fff0ef;color:#a72b20}.task-layout{display:grid;grid-template-columns:minmax(300px,420px) minmax(0,1fr);gap:14px;height:clamp(620px,calc(100vh - 250px),1080px);margin-top:14px}.task-list,.task-detail{min-height:0;overflow:auto;border:1px solid #e5e1d7;border-radius:15px;background:#fff}.task-list{display:grid;align-content:start;gap:8px;padding:10px}.task-card{display:grid!important;gap:7px;padding:13px!important;text-align:left}.task-card.active{border-color:#e0b31c;background:#fffaf0}.task-card>div:first-child{display:flex;justify-content:space-between}.task-card code,.task-card small{color:#77736b;font-size:10px}.pill{display:inline-flex;padding:3px 7px;border-radius:999px;font-size:10px}.good{background:#eafbf1;color:#067344}.warn{background:#fff4d3;color:#915d00}.bad{background:#ffefed;color:#ae281c}.muted{background:#f0efeb;color:#706d65}.progress{height:5px;overflow:hidden;border-radius:9px;background:#efede7}.progress i{display:block;height:100%;background:#e5b91f}.task-detail>header{position:sticky;top:0;z-index:2;display:flex;justify-content:space-between;padding:18px;border-bottom:1px solid #ece9e1;background:#fff}.task-detail h2{margin:5px 0}.task-detail header p{font-size:11px;word-break:break-all}.task-detail header button{width:38px;font-size:22px}.task-stats{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;padding:14px}.task-stats div{display:grid;gap:3px;padding:11px;border-radius:10px;background:#f7f6f1}.task-stats span{color:#79756c;font-size:10px}.unknown-note{margin:0 14px 12px;padding:11px;border:1px solid #efb3ac;border-radius:10px;background:#fff3f1;color:#a52a20}.task-items{display:grid;gap:7px;padding:0 14px 90px}.task-items article{display:grid;grid-template-columns:24px minmax(200px,1fr) auto minmax(130px,.4fr);gap:10px;align-items:start;padding:12px;border:1px solid #ebe8e0;border-radius:11px}.task-items strong,.task-items small{display:block}.task-items small{margin-top:4px;color:#77736b;font-size:10px}.task-items details{margin-top:7px}.task-items summary{color:#8c6100;font-size:10px}.task-items pre{max-height:160px;overflow:auto;white-space:pre-wrap;word-break:break-all}.checkbox-placeholder{width:16px}.task-detail>footer{position:sticky;bottom:0;display:flex;justify-content:flex-end;gap:8px;padding:12px 15px;border-top:1px solid #ebe8e0;background:#fff}.task-detail>footer button{padding:0 13px}.task-detail .danger{border-color:#e9a39b;color:#a9271c}.dialog-backdrop{position:fixed;inset:0;z-index:1200;display:grid;place-items:center;padding:16px;background:#18171366;backdrop-filter:blur(3px)}.cancel-dialog{width:min(500px,100%);padding:20px;border-radius:15px;background:#fff;box-shadow:0 20px 60px #0003}.cancel-dialog>header{display:flex;justify-content:space-between}.cancel-dialog h2{margin:5px 0}.cancel-dialog header button{width:38px;font-size:22px}.cancel-dialog>p{margin:12px 0}.cancel-dialog label{display:grid;gap:7px}.cancel-dialog textarea{padding:10px;border:1px solid #d9d5ca;border-radius:9px;resize:vertical}.cancel-dialog>footer{display:flex;justify-content:flex-end;gap:8px;margin-top:15px}.cancel-dialog>footer button{padding:0 13px}.empty{padding:70px 20px;text-align:center;color:#858178}@media(max-width:1500px){.task-center__filters{grid-template-columns:repeat(4,1fr)}}@media(max-width:1050px){.task-center__filters{grid-template-columns:repeat(3,1fr)}.task-layout{grid-template-columns:1fr;height:auto}.task-list{max-height:360px}.task-detail{height:min(70vh,760px);min-height:520px}}@media(max-width:600px){.task-center__header{align-items:flex-end}.task-center h1{font-size:22px}.task-center__filters{grid-template-columns:1fr}.task-layout{min-height:0}.task-list{max-height:320px}.task-detail{height:70vh;min-height:440px}.task-stats{grid-template-columns:repeat(2,1fr)}.task-items article{grid-template-columns:22px minmax(0,1fr) auto}.task-items article>small:last-child{grid-column:2/-1}.task-detail>footer{overflow:auto;justify-content:flex-start}.task-detail>footer button{flex:0 0 auto}}
</style>

<style scoped>
.qa-evidence{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-top:10px;padding:12px 14px;border:1px solid #e0b31c;border-radius:12px;background:#fff9dc;color:#614900}.qa-evidence div{display:grid;gap:3px}.qa-evidence span{font-size:12px;color:#796a39}.qa-evidence code{font-size:11px;white-space:nowrap}@media(max-width:600px){.qa-evidence{align-items:flex-start;flex-direction:column}.qa-evidence code{white-space:normal}}
</style>
